package repair

type Event struct { Seq int; ID,Kind,Key string; Delta int }
func ReplayEvents(events []Event) (map[string]int,bool) {
 state:=map[string]int{}
 for _,event:=range events { if event.Kind=="Add" { state[event.Key]+=event.Delta } else if event.Kind=="Delete" { delete(state,event.Key) } }
 return state,true
}

